// HasDocuments applies the HasEdge predicate on the "documents" edge.
func HasDocuments() predicate.RiderProfile {
	return predicate.RiderProfile(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.M2M, false, DocumentsTable, DocumentsPrimaryKey...),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasDocumentsWith applies the HasEdge predicate on the "documents" edge with a given conditions (other predicates).
func HasDocumentsWith(preds ...predicate.RiderDocument) predicate.RiderProfile {
	return predicate.RiderProfile(func(s *sql.Selector) {
		step := newDocumentsStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.RiderProfile) predicate.RiderProfile {
	return predicate.RiderProfile(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.RiderProfile) predicate.RiderProfile {
	return predicate.RiderProfile(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.RiderProfile) predicate.RiderProfile {
	return predicate.RiderProfile(sql.NotPredicates(p))
}
